<?php header("Content-Type: application/json; charset=UTF-8"); require_once "db.php"; try { if ($_SERVER["REQUEST_METHOD"] !== "POST") { throw new Exception("Invalid request method."); } $donation_id = intval($_POST["donation_id"] ?? 0); $user_id = intval($_POST["user_id"] ?? 0); $food_type = trim($_POST["food_type"] ?? ""); $quantity = trim($_POST["quantity"] ?? ""); $pickup_datetime = trim($_POST["pickup_datetime"] ?? ""); $expiry_datetime = trim($_POST["expiry_datetime"] ?? ""); $locality = trim($_POST["locality"] ?? ""); $location_name = trim($_POST["location_name"] ?? ""); $details = trim($_POST["details"] ?? ""); if ($donation_id <= 0 || $user_id <= 0) { throw new Exception("Invalid donation or user."); } if ( $food_type === "" || $quantity === "" || $pickup_datetime === "" || $expiry_datetime === "" || $locality === "" || $location_name === "" ) { throw new Exception("Please fill all required fields."); } $pickup = strtotime($pickup_datetime); $expiry = strtotime($expiry_datetime); if ($pickup === false || $expiry === false) { throw new Exception("Invalid date/time."); } if ($pickup <= time()) { throw new Exception("Pickup time must be in the future."); } if ($expiry <= $pickup) { throw new Exception("Expiry time must be after pickup time."); } /* * Only Available donations can be edited. */ $checkSql = " SELECT donation_id FROM food_donations WHERE donation_id = ? AND user_id = ? AND status = 'Available' LIMIT 1 "; $check = $conn->prepare($checkSql); $check->bind_param("ii", $donation_id, $user_id); $check->execute(); $result = $check->get_result(); if ($result->num_rows === 0) { throw new Exception( "This donation cannot be edited. It may already be claimed or deleted." ); } $check->close(); $sql = " UPDATE food_donations SET food_type = ?, quantity = ?, pickup_datetime = ?, expiry_datetime = ?, locality = ?, location_name = ?, details = ? WHERE donation_id = ? AND user_id = ? AND status = 'Available' "; $stmt = $conn->prepare($sql); if (!$stmt) { throw new Exception("Unable to prepare update query."); } $stmt->bind_param( "sssssssii", $food_type, $quantity, $pickup_datetime, $expiry_datetime, $locality, $location_name, $details, $donation_id, $user_id ); if (!$stmt->execute()) { throw new Exception("Unable to update donation."); } $stmt->close(); $conn->close(); echo json_encode([ "success" => true, "message" => "Food donation updated successfully." ]); } catch (Throwable $e) { http_response_code(500); echo json_encode([ "success" => false, "message" => $e->getMessage() ]); } ?>